:root {
  --bg-card: #1c1a2e;
  --bg-panel: #252340;
  --bg-header: #13112a;
  --accent-green: #39e08a;
  --accent-amber: #f5a623;
  --accent-red: #e05c5c;
  --accent-blue: #5cc8f5;
  --text-primary: #e8e4ff;
  --text-secondary: #8a85b8;
  --text-muted: #4a4870;
  --border-dim: #2e2c50;
  --band-track: #0d0c20;
  --flag-active-bg: #0e3024;
  --flag-active-text: #39e08a;
  --flag-warn-bg: #3a2800;
  --flag-warn-text: #f5a623;
  --flag-inactive-bg: #1e1c38;
  --flag-inactive-text: #4a4870;
}

.signal-log {
  width: 480px;
  background: var(--bg-card);
  border: 2px solid var(--border-dim);
  border-radius: 10px;
  overflow: hidden;
  font-size: 13px;
}

.log-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg-header);
  padding: 10px 16px;
  border-bottom: 2px solid var(--border-dim);
}

.header-left {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.log-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--accent-blue);
}

.log-id {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: 0.06em;
}

.dish-icon {
  font-size: 28px;
  line-height: 1;
}

.header-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}

.date-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: var(--text-secondary);
}

.log-date {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-amber);
  letter-spacing: 0.05em;
}

.log-body {
  display: grid;
  grid-template-columns: 140px 1fr 130px;
  gap: 0;
  border-bottom: 2px solid var(--border-dim);
}

.frequency-panel,
.readings-panel,
.status-panel {
  background: var(--bg-panel);
  padding: 12px 14px;
}

.frequency-panel {
  border-right: 1px solid var(--border-dim);
}

.readings-panel {
  border-right: 1px solid var(--border-dim);
}

.panel-title {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--text-secondary);
  margin: 0 0 8px 0;
}

.freq-row {
  display: flex;
  align-items: baseline;
  gap: 4px;
  margin-bottom: 10px;
}

.freq-value {
  font-size: 26px;
  font-weight: 700;
  color: var(--accent-green);
  line-height: 1;
  letter-spacing: -0.02em;
}

.freq-unit {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
}

.band-bar {
  position: relative;
  height: 8px;
  background: var(--band-track);
  border-radius: 4px;
  margin-bottom: 4px;
  overflow: visible;
}

.band-fill {
  width: 28%;
  height: 100%;
  background: var(--accent-green);
  border-radius: 4px;
  opacity: 0.7;
}

.band-marker {
  position: absolute;
  top: -3px;
  left: calc(28% - 3px);
  width: 6px;
  height: 14px;
  background: var(--accent-green);
  border-radius: 2px;
}

.band-labels {
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  font-weight: 600;
  color: var(--text-muted);
  letter-spacing: 0.05em;
  margin-top: 2px;
}

.readings-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.reading-item {
  display: flex;
  align-items: baseline;
  gap: 4px;
}

.reading-name {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-secondary);
  letter-spacing: 0.08em;
  min-width: 46px;
}

.reading-dots {
  flex: 1;
  border-bottom: 1px dotted var(--text-muted);
  margin-bottom: 2px;
}

.reading-val {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
  white-space: nowrap;
}

.flags-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px;
  margin-bottom: 10px;
}

.flag {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-align: center;
  padding: 4px 2px;
  border-radius: 4px;
}

.flag-active {
  background: var(--flag-active-bg);
  color: var(--flag-active-text);
  border: 1px solid var(--accent-green);
}

.flag-warn {
  background: var(--flag-warn-bg);
  color: var(--flag-warn-text);
  border: 1px solid var(--accent-amber);
}

.flag-inactive {
  background: var(--flag-inactive-bg);
  color: var(--flag-inactive-text);
  border: 1px solid var(--text-muted);
}

.operator-row {
  display: flex;
  flex-direction: column;
  gap: 2px;
  border-top: 1px solid var(--border-dim);
  padding-top: 8px;
}

.op-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--text-secondary);
}

.op-name {
  font-size: 11px;
  font-weight: 700;
  color: var(--accent-blue);
  letter-spacing: 0.04em;
}

.log-footer {
  background: var(--bg-header);
}

.footer-stripe {
  height: 3px;
  background: repeating-linear-gradient(
    90deg,
    var(--accent-green) 0px,
    var(--accent-green) 12px,
    var(--bg-card) 12px,
    var(--bg-card) 16px
  );
}

.footer-content {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px;
}

.source-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--text-secondary);
}

.source-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: 0.04em;
  flex: 1;
}

.classification {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--accent-amber);
  border: 1px solid var(--accent-amber);
  border-radius: 4px;
  padding: 2px 7px;
}
